 function go(patch:Partial<Route>,remember=true){setNavigationRevision(value=>value+1);recognitionOrigin.current=null;stopAudio();setQuery('');setShowGrammar(false);setWriting(false);if(remember)setTrail(t=>[...t,route].slice(-24));const next={...route,...patch};setRoute(next);history.pushState(null,'',href(next));if(patch.stage||patch.hanzi)requestAnimationFrame(()=>{if(!matchMedia('(max-width:760px)').matches)return;const root=document.querySelector('.cloud-context-layout');const target=root?.querySelector('.cloud-tour')??(next.layout==='family'?root?.querySelector('.cloud-context-surface'):root?.querySelector('[data-context-stage="'+next.stage+'"]'));if(target){const box=target.getBoundingClientRect();if(box.top<0||box.bottom>innerHeight)target.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}});}
